import sys

rows = sys.stdin.read().split()[:9]
g = [[0 if c == '.' else int(c) for c in r] for r in rows]

def ok(i, j, v):
    for k in range(9):
        if g[i][k] == v or g[k][j] == v:
            return False
    bi, bj = i // 3 * 3, j // 3 * 3
    for a in range(3):
        for b in range(3):
            if g[bi + a][bj + b] == v:
                return False
    return True

def solve():
    for i in range(9):
        for j in range(9):
            if g[i][j] == 0:
                for v in range(1, 10):
                    if ok(i, j, v):
                        g[i][j] = v
                        if solve():
                            return True
                        g[i][j] = 0
                return False
    return True

solve()
print('\n'.join(''.join(map(str, r)) for r in g))

